func composeDirection(medium, mood, palette string) string {
	parts := make([]string, 0, 3)
	// Palette FIRST (bugs_open/027 4b): the composed direction is truncated at
	// maxImageryDirectionInPrompt; palette is the shortest, most identity-
	// bearing field and must not be the tail. medium/mood degrade gracefully.
	if palette != "" {
		parts = append(parts, "colour palette: "+palette)
	}
	if medium != "" {
		parts = append(parts, medium)
	}
	if mood != "" {
		parts = append(parts, mood)
	}
	return strings.Join(parts, ". ")
}

func composeImagePromptWithDirection(prompt, direction string) (string, bool) {
	prompt = strings.TrimSpace(prompt)
	direction = strings.TrimSpace(direction)
	if prompt == "" || direction == "" {
		return prompt, false
	}
	truncated := len(direction) > maxImageryDirectionInPrompt
	if truncated {
		cut := datahelpers.SafeCut(direction, maxImageryDirectionInPrompt)
		minKeep := maxImageryDirectionInPrompt / 2
		// LAST '. ' within the cap (r5): with a long leading clause, first-'. '
		// cuts at its end, discarding later clauses that fit.
		if idx := strings.LastIndex(cut, ". "); idx > minKeep {
			cut = cut[:idx+1]
		} else if idx := strings.LastIndex(cut, ", "); idx > minKeep {
			cut = cut[:idx]
		}
		direction = strings.TrimSpace(cut)
	}
	sep := ". "
	if endsWithSentenceBoundary(direction) {
		sep = " "
	}
	return direction + sep + prompt, truncated
}
